/**
 * Treasury Orchestration Module
 * 
 * A tool for AI agents to autonomously manage funds through Crossmint wallets.
 * 
 * Environment Variables Required:
 * - CROSSMINT_API_KEY: Crossmint API key for authentication
 * - SIGNER_SECRET: Signer secret for wallet operations
 */

const { WalletsSDK } = require('@crossmint/wallets-sdk');

/**
 * Executes a treasury action based on the provided action type.
 * 
 * @param {Object} action - The action to execute
 * @param {string} action.type - The type of action ('create_wallet', 'check_balance', 'mint_receipt')
 * @returns {Promise<Object>} Result object with success status and relevant data
 */
async function executeTreasuryAction(action) {
    const apiKey = process.env.CROSSMINT_API_KEY;
    const signerSecret = process.env.SIGNER_SECRET;

    if (!apiKey) {
        return { success: false, error: 'CROSSMINT_API_KEY environment variable not set' };
    }

    const sdk = new WalletsSDK({
        apiKey: apiKey,
        ...(signerSecret && { signerSecret: signerSecret })
    });

    try {
        switch (action.type) {
            case 'create_wallet': {
                const { userId, chain } = action;

                if (!userId || !chain) {
                    return { success: false, error: 'Missing required fields: userId, chain' };
                }

                // Create EVM smart wallet using Crossmint SDK
                const wallet = await sdk.wallets.create({
                    type: 'evm-smart-wallet',
                    config: {
                        userId: userId,
                        chain: chain
                    }
                });

                return {
                    success: true,
                    address: wallet.address,
                    chain: chain,
                    userId: userId
                };
            }

            case 'check_balance': {
                const { walletAddress, chain } = action;

                if (!walletAddress || !chain) {
                    return { success: false, error: 'Missing required fields: walletAddress, chain' };
                }

                // Query wallet balance using Crossmint SDK
                const balance = await sdk.wallets.getBalance(walletAddress, chain);

                return {
                    success: true,
                    walletAddress: walletAddress,
                    chain: chain,
                    balance: balance.toString()
                };
            }

            case 'mint_receipt': {
                const { email, purchaseId } = action;

                if (!email || !purchaseId) {
                    return { success: false, error: 'Missing required fields: email, purchaseId' };
                }

                // Mint "Purchase Receipt" NFT using Crossmint minting API
                // Note: Using the SDK's minting functionality for NFTs
                const mintResult = await sdk.nfts.mint({
                    chain: 'polygon-amoy',
                    recipient: email,
                    metadata: {
                        name: 'Purchase Receipt',
                        description: `Receipt for purchase ${purchaseId}`,
                        image: '',
                        attributes: [
                            {
                                trait_type: 'Purchase ID',
                                value: purchaseId
                            },
                            {
                                trait_type: 'Type',
                                value: 'Receipt'
                            }
                        ]
                    }
                });

                return {
                    success: true,
                    email: email,
                    purchaseId: purchaseId,
                    actionId: mintResult.id || mintResult.actionId || 'unknown'
                };
            }

            default:
                return { success: false, error: 'Unknown action type' };
        }
    } catch (error) {
        console.error(`Error executing action ${action.type}:`, error.message);
        return {
            success: false,
            error: error.message,
            actionType: action.type
        };
    }
}

module.exports = { executeTreasuryAction };

