        chain: 'base-sepolia'
    };
    results.push(await runTest('check_balance', checkBalanceAction));

    // Test 3: Mint Receipt
    const mintReceiptAction = {
        type: 'mint_receipt',
        email: 'test@example.com',
        purchaseId: 'purchase-' + Date.now()
    };
    results.push(await runTest('mint_receipt', mintReceiptAction));

    // Test 4: Unknown Action Type (error handling test)
    const unknownAction = {
        type: 'unknown_action',
        someField: 'value'
    };
    results.push(await runTest('unknown_action', unknownAction));

    // Write results to JSON file
    const resultsPath = '/home/user/treasury_test_results.json';
